    "750": ["Colleague 1", "Colleague 3", "Colleague 4", "Colleague 6", "Colleague 7", "Colleague 10", "Colleague 11", "Colleague 12", "Colleague 15", "Colleague 16", "Colleague 17", "Colleague 18"],
    "700": ["Colleague 2", "Colleague 5", "Colleague 8", "Colleague 9", "Colleague 13", "Colleague 14"]
  },
  "consensus_items": {
    "bets_margin": "600 points unanimously agreed across all 18 colleagues.",
    "bet_breakdown": "Player A1 (1st place) makes Grand Tichu (+200). A2 calls nothing (0). Both B1 and B2 call Grand Tichu and fail (-200 * 2 = -400). Swing = 200 - (-400) = 600."
  },
  "the_single_dispute": "Card points margin: 150 (from +125 vs -25) yielding 750, vs. 100 (from +100 vs 0 with a supposed floor at 0) yielding 700.",
  "analysis_of_dispute": {
    "pro_750_arguments": [
      "Physical card count: The positive cards in the deck physically sum to +125 (four 5s = 20, four 10s = 40, four Kings = 40, Dragon = 25). The Phoenix is -25. Net deck sum = 100.",
      "Rulebook instructions: Official rules (Urs Hostettler, Fata Morgana, Rio Grande, Z-Man) instruct players to simply sum the card points in their captured trick pile. There is no zero-floor clause anywhere in any published edition.",
      "Conservation of points: Cards_A + Cards_B = 125 + (-25) = 100. Flooring Team B at 0 would either mean Cards_A + Cards_B = 125 != 100, or arbitrarily deleting 25 points physically won by Team A.",
      "Digital / Tournament reality: Implementations like Board Game Arena (BGA), BrettspielWelt (BSW), and Yucata literally evaluate card points algebraically, registering +125 to -25 if a player takes only the Phoenix.",
      "Dragon mechanics: Bombing the Dragon trick or winning it through the opponent avoids having to surrender the Dragon trick to the losing team."
    ],
    "pro_700_arguments": [
      "Assert that trick points are bounded in [0, 100] as a partition of the 100-point deck.",
      "Claim that Phoenix is only an offset against positive card points won, and trick totals cannot be negative.",
      "Claim that a team cannot receive 125 points from a 100-point deck."
    ],
    "flaws_in_pro_700": [
      "The claim of a [0, 100] bound is an unwritten assumption/fabrication; the rules never state card scores cannot be negative.",
      "The deck does not contain only 100 positive points; it contains 125 positive points and 25 negative points. The net is 100. A team holding all positive points holds 125 points."
    ]
  },
  "firm_position": "750 is strictly correct mathematically and under the official rules of Tichu."
}

